const $=id=>document.getElementById(id);let state={commitment:FP.commitment('valid'),evidence:null,result:null,appeals:0,reserved:false};
function notice(message){$('notice').className=message?'error':'';$('notice').textContent=message;if(message)$('notice').scrollIntoView({block:'center',behavior:'smooth'});}
let role='candidate';
function setRole(next){role=next;$('candidate-review').hidden=next==='employer';$('employer-panel').hidden=next!=='employer';$('role-state').textContent=next==='employer'?'VISTA DEL EMPLEADOR · SIMULACIÓN':'VISTA DE CANDIDATA';}
$('show-employer').onclick=()=>{setRole('employer');notice('');$('employer-panel').scrollIntoView({block:'start',behavior:'smooth'});};
$('back-candidate').onclick=()=>{setRole('candidate');notice('');};
function screen(n){setRole('candidate');['conditions','evidence','review','outcome'].forEach((id,i)=>$(id).hidden=i!==n);document.querySelectorAll('#steps li').forEach((el,i)=>el.classList.toggle('active',i===n));const titles=['Tu experiencia merece un siguiente paso.','Muestra lo que ya sabes hacer.','Tu evidencia está pendiente de revisión.','Una puerta, con condiciones claras.'];$('heading').textContent=titles[n];$('chapter').textContent=`0${n+1} / ${['CONDICIONES','MI EVIDENCIA','REVISIÓN HUMANA','SIGUIENTE PASO'][n]}`;$('intro').textContent=['Conoce las condiciones antes de invertir tu tiempo.','Trabaja con el ejemplo ficticio. No incluyas información personal.','Estás en la vista de candidata. No necesitas evaluar tu propia evidencia.','Todo resultado en esta pantalla es simulado.'][n];notice('');window.scrollTo({top:0,behavior:'smooth'});}
function line(container,label,value){const div=document.createElement('div');div.className='data-line';const small=document.createElement('small');small.textContent=label;div.append(small,document.createTextNode(String(value)));container.append(div);}
$('scenario').onchange=()=>{state.commitment=FP.commitment($('scenario').value);const blocked=FP.gate(state.commitment);$('capacity').textContent=`${state.commitment.capacity} cupos simulados`;$('start').disabled=!!blocked;notice(blocked);};
$('start').onclick=()=>{const err=FP.gate(state.commitment);if(err)return notice(err);for(const [k,v] of Object.entries(FP.example))$(k).value=v;screen(1);};
$('evidence-form').onsubmit=e=>{e.preventDefault();const ev={};for(const k of ['problem','contribution','result','type'])ev[k]=$(k).value.trim();for(const k of ['record','count'])ev[k]=$ (k).value===''?NaN:Number($(k).value);const err=FP.validate(ev);if(err)return notice(err);if(!$('fictional').checked)return notice('Confirma que solo usas datos ficticios.');state.evidence=ev;const suggestion=$('suggestion');suggestion.replaceChildren();line(suggestion,'Problema',ev.problem);line(suggestion,'Aportación declarada',ev.contribution);line(suggestion,'Cálculo reproducible',`${ev.record} - ${ev.count} = ${ev.record-ev.count} unidades de diferencia.`);line(suggestion,'Límite de la evidencia',FP.provenance(ev));line(suggestion,'Sugerencia simulada','Pregunta por qué se investigan los movimientos antes de corregir el registro. No atribuyas una mejora sin respaldo.');screen(2);};
$('review-form').onsubmit=e=>{e.preventDefault();if(role!=='employer')return notice('Abre la simulación del empleador para probar esta decisión.');const reason=$('reason').value.trim();const criteria=['c1','c2','c3'].map(k=>$(k).checked);const result=FP.decide(state,criteria,reason,$('recheck').value);if(result.error)return notice(result.error);if(result.status==='interview'){state.commitment.capacity=result.capacity;state.reserved=true;}state.result={...result,reason,criteria,fictional:true,ai:'simulated',provenance:FP.provenance(state.evidence)};renderOutcome();};
function renderOutcome(){screen(3);const r=state.result;$('outcome-title').textContent={interview:'Entrevista simulada habilitada',feedback:'Retroalimentación específica',blocked:'Compromiso bloqueado',paused:'Pausa para acordar el pago'}[r.status];$('outcome-description').textContent=r.text;const proof=$('proof');proof.replaceChildren();line(proof,'Razón de la revisión humana simulada',r.reason);line(proof,'Respaldo del resultado',r.provenance);line(proof,'Mi aportación',state.evidence.contribution);line(proof,'Acceso a la evidencia','Solo esta sesión; no se comparte con ningún empleador. Tú decides si descargas el archivo.');const metrics=$('metrics');metrics.replaceChildren();[['Revisiones simuladas',1+state.appeals],['Entrevistas simuladas',state.reserved?1:0],['Ofertas / trabajo pagado','0 / 0']].forEach(([a,b])=>{const d=document.createElement('div');line(d,a,b);metrics.append(d);});$('appeal').disabled=state.appeals>=1||r.status!=='feedback';$('appeal-note').textContent=state.appeals?'Ya solicitaste la segunda revisión del demo. No se agregan más pruebas.':r.status==='feedback'?'Puedes pedir una segunda revisión de la misma evidencia; no necesitas empezar de nuevo.':r.status==='interview'?'La segunda revisión está disponible cuando recibes retroalimentación sin avanzar a entrevista. Este ejemplo ya habilitó una entrevista simulada.':'La segunda revisión de criterios no está disponible mientras el compromiso esté bloqueado o la evaluación pausada.';}
$('appeal').onclick=()=>{if(state.appeals>=1||state.result.status!=='feedback')return;state.appeals++;$('reason').value='';screen(2);notice('Segunda revisión: conserva la misma evidencia y explica qué decisión corriges. En el piloto real revisaría otra persona.');};
$('export').onclick=()=>{const payload={label:'DEMO: fictional data; simulated AI and human role-play; not a credential or real interview',role:FP.seed.role,evidence:state.evidence,review:state.result,interviews:state.reserved?1:0,offers:0,paidWork:0};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='first-proof-evidencia-ficticia.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('reset').onclick=()=>{state={commitment:FP.commitment('valid'),evidence:null,result:null,appeals:0,reserved:false};$('scenario').value='valid';$('recheck').value='valid';$('start').disabled=false;$('capacity').textContent='2 cupos simulados';$('evidence-form').reset();$('review-form').reset();screen(0);};
